class Node:
    def __init__(self, key):
        self.key, self.left, self.right, self.height = key, None, None, 1

def height(n): return n.height if n else 0
def update(n): n.height = 1 + max(height(n.left), height(n.right))
def balance(n): return height(n.left) - height(n.right) if n else 0

def rotate_right(y):
    x = y.left
    y.left, x.right = x.right, y
    update(y)
    update(x)
    return x

def rotate_left(x):
    y = x.right
    x.right, y.left = y.left, x
    update(x)
    update(y)
    return y

def rebalance(n):
    if not n: return None
    update(n)
    if balance(n) > 1:
        if balance(n.left) < 0: n.left = rotate_left(n.left)
        return rotate_right(n)
    if balance(n) < -1:
        if balance(n.right) > 0: n.right = rotate_right(n.right)
        return rotate_left(n)
    return n

def insert(n, key):
    if not n: return Node(key)
    if key < n.key: n.left = insert(n.left, key)
    elif key > n.key: n.right = insert(n.right, key)
    else: return n  # set semantics: duplicate keys are ignored
    return rebalance(n)

def erase(n, key):
    if not n: return None
    if key < n.key: n.left = erase(n.left, key)
    elif key > n.key: n.right = erase(n.right, key)
    else:
        if not n.left: return n.right
        if not n.right: return n.left
        successor = n.right
        while successor.left: successor = successor.left
        n.key = successor.key
        n.right = erase(n.right, successor.key)
    return rebalance(n)

