    explicit Node(int k):key(k){}
};
int height(Node* n){return n?n->height:0;}
int balance(Node* n){return n?height(n->left)-height(n->right):0;}
void update(Node* n){n->height=1+std::max(height(n->left),height(n->right));}
Node* rotateRight(Node* y){Node* x=y->left;y->left=x->right;x->right=y;update(y);update(x);return x;}
Node* rotateLeft(Node* x){Node* y=x->right;x->right=y->left;y->left=x;update(x);update(y);return y;}
Node* rebalance(Node* n){
    if(!n)return n;
    update(n);
    if(balance(n)>1){if(balance(n->left)<0)n->left=rotateLeft(n->left);return rotateRight(n);}
    if(balance(n)<-1){if(balance(n->right)>0)n->right=rotateRight(n->right);return rotateLeft(n);}
    return n;
}
Node* insert(Node* n,int key){
    if(!n)return new Node(key);
    if(key<n->key)n->left=insert(n->left,key);
    else if(key>n->key)n->right=insert(n->right,key);
    else return n;
    return rebalance(n);
}
Node* erase(Node* n,int key){
    if(!n)return n;
    if(key<n->key)n->left=erase(n->left,key);
    else if(key>n->key)n->right=erase(n->right,key);
    else{
        if(!n->left||!n->right){Node* child=n->left?n->left:n->right;delete n;return child;}
        Node* s=n->right;while(s->left)s=s->left;
        n->key=s->key;n->right=erase(n->right,s->key);
    }
    return rebalance(n);
}
void destroy(Node* n){if(n){destroy(n->left);destroy(n->right);delete n;}}
