  static Node rotateLeft(Node x){Node y=x.right;x.right=y.left;y.left=x;update(x);update(y);return y;}
  static Node rebalance(Node n){
    if(n==null)return n;update(n);
    if(balance(n)>1){if(balance(n.left)<0)n.left=rotateLeft(n.left);return rotateRight(n);}
    if(balance(n)<-1){if(balance(n.right)>0)n.right=rotateRight(n.right);return rotateLeft(n);}
    return n;
  }
  static Node insert(Node n,int key){
    if(n==null)return new Node(key);
    if(key<n.key)n.left=insert(n.left,key);
    else if(key>n.key)n.right=insert(n.right,key);else return n;
    return rebalance(n);
  }
